from __future__ import annotations

from typing import Any

_MODEL_CACHE: dict[str, Any] = {}


def clear_model_cache() -> int:
    """Drop cached WhisperModel instances so GC can free VRAM."""
    n = len(_MODEL_CACHE)
    _MODEL_CACHE.clear()
    try:
        import gc

        gc.collect()
    except Exception:
        pass
    # Do not import torch here: on Windows its bundled cublas can WinError 999
    # after nvidia-cublas is mapped for CT2, and empty_cache is unnecessary once
    # WhisperModel refs are dropped.
    return n


def _get_cached_whisper_model(
    WhisperModel: Any,
    model_dir: str,
    *,
    device: str,
    compute_type: str,
) -> Any:
    key = f"{model_dir}|{device}|{compute_type}"
    cached = _MODEL_CACHE.get(key)
    if cached is not None:
        return cached
    model = WhisperModel(model_dir, device=device, compute_type=compute_type)
    _MODEL_CACHE[key] = model
    return model
